name: CI

on:
  pull_request:
  push:
    branches: [main]
  merge_group:

concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  lint:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - &checkout
        uses: actions/checkout@v4
      - &node
        uses: actions/setup-node@v4
        with:
          node-version: 22
      - &modules
        uses: actions/cache@v4
        id: modules
        with:
          path: node_modules
          key: modules-${{ runner.os }}-${{ runner.arch }}-node22-${{ hashFiles('package-lock.json', 'package.json', '.npmrc') }}
      - &install
        if: steps.modules.outputs.cache-hit != 'true'
        run: npm ci
      - run: npm run lint

  typecheck:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - *checkout
      - *node
      - *modules
      - *install
      - run: npm run typecheck

  test:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - *checkout
      - *node
      - *modules
      - *install
      - run: npm test -- --reporter=default --reporter=json --outputFile.json="$RUNNER_TEMP/vitest.json"
      - name: Slowest test files
        env:
          REPORT: ${{ runner.temp }}/vitest.json
        run: |
          node --input-type=module <<'EOF'
          import { readFileSync } from "node:fs";
          const limit = 10;
          const root = process.cwd().replaceAll("\\", "/") + "/";
          const files = JSON.parse(readFileSync(process.env.REPORT, "utf8")).testResults
            .map(f => ({ file: f.name.replace(root, ""), seconds: (f.endTime - f.startTime) / 1000 }))
            .sort((a, b) => b.seconds - a.seconds);
          console.log("Slowest 10 test files:");
          for (const f of files.slice(0, 10)) console.log(`${f.seconds.toFixed(2).padStart(7)} s  ${f.file}`);
          const slow = files.filter(f => f.seconds > limit);
          for (const f of slow) console.log(`::error file=${f.file}::${f.file} took ${f.seconds.toFixed(1)} s; a test file may take at most ${limit} s. Split it, or mock the slow part (AGENTS.md Tests).`);
          if (slow.length) process.exit(1);
          EOF

  build:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - *checkout
      - *node
      - *modules
      - *install
      - uses: actions/cache@v4
        with:
          path: .next/cache
          key: next-.next-${{ runner.os }}-${{ hashFiles('package-lock.json') }}-${{ github.sha }}
          restore-keys: next-.next-${{ runner.os }}-${{ hashFiles('package-lock.json') }}-
      - run: npm run build
      - run: npm run check:bundle

  database:
    runs-on: ubuntu-latest
    timeout-minutes: 20
    steps:
      - *checkout
      - *node
      - *modules
      - *install
      - name: Start the test backend
        run: |
          for attempt in 1 2 3 4; do
            npm run setup -- --qa && exit 0
            echo "::warning::Starting the test backend failed (attempt $attempt); the image registry limits pulls. Trying again."
            sleep $((attempt * 30))
          done
          exit 1
      - name: Check the generated database types are current
        run: |
          npm run db:types
          git diff --exit-code lib/database.types.ts || { echo "::error file=lib/database.types.ts::The migrations and lib/database.types.ts disagree. Run npm run db:types and commit the result."; exit 1; }
      - run: npm run test:db

  browser:
    runs-on: ubuntu-latest
    timeout-minutes: 25
    env:
      E2E_BASE_URL: http://localhost:3100
    steps:
      - *checkout
      - *node
      - *modules
      - *install
      - uses: actions/cache@v4
        with:
          path: ~/.cache/ms-playwright
          key: playwright-${{ runner.os }}-${{ hashFiles('package-lock.json') }}
      - uses: actions/cache@v4
        with:
          path: .next-qa/cache
          key: next-.next-qa-${{ runner.os }}-${{ hashFiles('package-lock.json') }}-${{ github.sha }}
          restore-keys: next-.next-qa-${{ runner.os }}-${{ hashFiles('package-lock.json') }}-
      - name: Start the test backend, the QA app and the browser install together
        run: |
          npx playwright install --only-shell chromium > "$RUNNER_TEMP/playwright.log" 2>&1 &
          playwright=$!
          (
            for attempt in 1 2 3 4; do
              npm run setup -- --qa && exit 0
              echo "::warning::Starting the test backend failed (attempt $attempt); the image registry limits pulls. Trying again."
              sleep $((attempt * 30))
            done
            exit 1
          ) &
          backend=$!
          until [ -s .env.qa ] || ! kill -0 $backend 2>/dev/null; do sleep 1; done
          nohup node scripts/qa-server.mjs --production > "$RUNNER_TEMP/qa-server.log" 2>&1 &
          echo $! > "$RUNNER_TEMP/qa-server.pid"
          wait $backend
          wait $playwright || { cat "$RUNNER_TEMP/playwright.log"; exit 1; }
      - run: npm run qa:auth
      - name: Wait for the QA app
        timeout-minutes: 5
        run: |
          until curl -s -o /dev/null http://localhost:3100/api/health; do
            kill -0 "$(cat "$RUNNER_TEMP/qa-server.pid")" 2>/dev/null || { cat "$RUNNER_TEMP/qa-server.log"; exit 1; }
            sleep 2
          done
      - name: Browser journeys
        run: npm run test:e2e -- --workers=1 --retries=1 e2e/net-worth.gated.spec.ts e2e/import-journey.mocked.spec.ts
      - name: QA app log
        if: failure()
        run: cat "$RUNNER_TEMP/qa-server.log"
      - name: Upload failure traces and screenshots
        if: failure()
        uses: actions/upload-artifact@v4
        with:
          name: browser-failures
          path: test-results/
          retention-days: 7
          if-no-files-found: ignore

  checks:
    if: always()
    needs: [lint, typecheck, test, build, database, browser]
    runs-on: ubuntu-latest
    timeout-minutes: 2
    steps:
      - if: contains(needs.*.result, 'failure') || contains(needs.*.result, 'cancelled') || contains(needs.*.result, 'skipped')
        run: exit 1
